/* Tamil strings for the Vijnana lessons: B3 journey of a roti, K2 the ramp test, R1 the lamp and the stick. Draft translation: needs review by a native-speaker teacher. */
window.Sutra.i18n.add('ta', {
  /* B3 */
  'prashna.B3.q': 'ஒரு பெரியவரின் சிறுகுடல் சுமார் 6 m நீளம். அது அவர்களின் உயரத்தின் எத்தனை மடங்கு?',
  'prashna.B3.c1': 'உயரத்தின் பாதி அளவு', 'prashna.B3.c2': 'உயரத்துக்கு சமம்', 'prashna.B3.c3': 'உயரத்தின் நான்கு மடங்கு',
  'prashna.B3.a': 'சுமார் நான்கு மடங்கு. சுருள் வடிவில் இருப்பதால் உடலில் பொருந்தும்; நீளம் உணவுக்கு இரத்தத்தில் சேர நேரம் தரும்.',
  'dig.lengthArt': '1.5 m உயரமுள்ள பெரியவர், பக்கத்தில் சுருள் வடிவில் சுமார் 6 m நீளக் குழாய்.',
  'dig.smallLen': 'சுமார் 6 m',
  'bodha.B3.what': 'உடலால் ரொட்டியை அப்படியே பயன்படுத்த முடியாது. [[digestion|செரிமானம்]] உணவை இரத்தத்தில் சேரும் அளவுக்கு சிறிய துண்டுகளாக உடைக்கும்.',
  'bodha.B3.can': 'நீ உடலில் உணவின் வழியை வரிசையில் பின்தொடர்ந்து, பெரும்பால் எங்கே இரத்தத்தில் சேர்கிறது என்று சொல்ல முடியும்.',
  'bodha.B3.idea': 'உணவின் பயணத்தில் ஐந்து நிறுத்தங்கள்: வாய், உணவுக்குழாய், இரைப்பை, சிறுகுடல், பெருங்குடல்.',
  'bodha.B3.why': 'இரத்தம் மிகச் சிறிய துண்டுகளை மட்டுமே எடுத்துச் செல்லும். அவற்றில் பெரும்பால் [[intestine|சிறுகுடல்]] சுவர்கள் வழியே இரத்தத்தில் சேரும்; இரைப்பையில் அல்ல.',
  'bodha.B3.example': 'ரொட்டியின் ஒரு கடி பயணத்தைப் பார்.',
  'bodha.B3.example1': 'வாய்: பற்கள் மெல்லும்; உமிழ்நீர் உடைக்கத் தொடங்கும்.',
  'bodha.B3.example2': 'உணவுக்குழாய், பின்னர் இரைப்பை: சில வினாடிகளில் கீழே செல்லும்; பின்னர் 2 முதல் 4 மணி நேரம் கலக்கி கலக்கும்.',
  'bodha.B3.example3': 'சிறுகுடல்: செரிமானம் முடிவு; சிறிய துண்டுகள் இரத்தத்தில் சேரும். பெருங்குடல் நீரைத் திரும்ப எடுக்கும்.',
  'bodha.B3.where': 'நன்றாக மெல்லுதல் செரிமானத்துக்கு உதவும். காய்கறிகளும் நீரும் கழிவு முன்னே செல்ல உதவும். சிறுநீரகம் இரத்தத்தைச் சுத்தம் செய்து சிறுநீர் உருவாக்கும்.',
  'bodha.B3.sutra': 'செரிமானம் உணவை இரத்தம் எடுத்துச் செல்லும் அளவுக்கு சிறியதாக்கும்; உடல் பயன்படுத்தாததை வெளியேற்றும்.',
  'gloss.digestion': 'உடல் உள்ளே எடுத்துக்கொள்ள உணவை உடைத்தல்.',
  'gloss.intestine': 'இரைப்பைக்குப் பிறகு உள்ள நீண்ட, சுருள் குழாய்; அங்கே உணவு இரத்தத்தில் சேரும்.',
  'dig.art': 'உடலில் உணவின் பாதை: வாய், உணவுக்குழாய், இரைப்பை, சிறுகுடல், பெருங்குடல்.',
  'dig.o.mouth': 'வாய்', 'dig.o.pipe': 'உணவுக்குழாய்', 'dig.o.stomach': 'இரைப்பை', 'dig.o.small': 'சிறுகுடல்', 'dig.o.large': 'பெருங்குடல்',
  'dig.title': 'ரொட்டியின் பயணம்',
  'dig.s1': 'ரொட்டியின் ஒரு கடி உடலில் பயணிப்பதைப் பார்.',
  'dig.showMe': 'ரொட்டியைப் பின்தொடர்',
  'dig.say.mouth': 'வாய்: பற்கள் ரொட்டியை மெல்லும்; உமிழ்நீர் உடைக்கத் தொடங்கும்.',
  'dig.say.pipe': 'உணவுக்குழாய்: தசைகள் உணவை சில வினாடிகளில் இரைப்பைக்கு தள்ளும்.',
  'dig.say.stomach': 'இரைப்பை: 2 முதல் 4 மணி நேரம் உணவைக் கலக்கி கலக்கும்.',
  'dig.say.small': 'சிறுகுடல்: செரிமானம் முடிவு; சிறிய துண்டுகள் இரத்தத்தில் சேரும்.',
  'dig.say.large': 'பெருங்குடல்: நீர் திரும்ப எடுக்கப்படும்; உடல் பயன்படுத்தாதது வெளியேறும்.',
  'dig.s1done': 'ஐந்து நிறுத்தங்கள், எப்போதும் அதே வரிசை.',
  'dig.s2': 'நிறுத்தங்களை வரிசைப்படுத்து: முதலிலிருந்து கடைசி வரை தொடு.',
  'dig.notFirst': 'உணவின் ஒரு கடி முதலில் எங்கே போகிறது?',
  'dig.notYet': '{last}-க்கு அடுத்து உணவு எங்கே போகிறது?',
  'dig.s2done': 'வாய், உணவுக்குழாய், இரைப்பை, சிறுகுடல், பெருங்குடல்.',
  'dig.s3': 'பெரும்பாலான உணவு இரத்தத்தில் சேரும் இடத்தைத் தொடு.',
  'dig.s3done': 'சிறுகுடல். நீண்ட, மடிந்த சுவர்கள் சிறிய உணவுத் துண்டுகள் இரத்தத்தில் சேர உதவும்.',
  'dig.s3try': 'உணவு {o} வழியே செல்கிறது, ஆனால் அங்கே பெரும்பாலும் இரத்தத்தில் சேராது. வேறு நிறுத்தம் முயற்சி.',
  'mistake.B3.intro': 'ரோஹன் உணவு எங்கே போகிறது என்று விளக்கினான். ஒரு படி தவறு. எது?',
  'mistake.B3.s1': 'முதலில் வாயில் ரொட்டியை மெல்கிறோம்.',
  'mistake.B3.s2': 'உணவுக்குழாய் அதை இரைப்பைக்கு கீழே கொண்டு செல்கிறது.',
  'mistake.B3.s3': 'இரைப்பை உணவை இரத்தத்தில் சேர்க்கிறது.',
  'mistake.B3.s4': 'மீதம் குடல்களுக்குச் செல்கிறது.',
  'mistake.B3.fine1': 'சரி: செரிமானம் வாயில் தொடங்கும்.',
  'mistake.B3.fine2': 'சரி: உணவுக்குழாய் வாயையும் இரைப்பையையும் இணைக்கிறது.',
  'mistake.B3.fine4': 'உணவு குடல்களுக்குச் செல்வது உண்மை. முன்னால் பார்.',
  'mistake.B3.found': 'இங்கே. இரைப்பை உணவைக் கலக்கி கலக்கும், ஆனால் பெரும்பாலான உணவு சிறுகுடலில் இரத்தத்தில் சேரும்.',
  'explain.B3.s': 'உணவு உடைக்கப்பட்டு {0}-ல் சேர முடியும். இதில் பெரும்பால் {1}-ல் நடக்கும்.',
  'explain.B3.blood': 'இரத்தம்', 'explain.B3.air': 'காற்று', 'explain.B3.bones': 'எலும்புகள்',
  'explain.B3.stomach': 'இரைப்பை', 'explain.B3.small': 'சிறுகுடல்', 'explain.B3.mouth': 'வாய்',
  'explain.B3.hint': 'பாதையைப் பார்: எந்த நிறுத்தத்திலிருந்து சிவப்பு புள்ளிக்கோடு இரத்தத்துக்குப் போகிறது?',
  'know.B3': 'செரிமானம் உணவை இரத்தம் எடுத்துச் செல்லும் அளவுக்கு சிறியதாக்கும்; பெரும்பாலும் சிறுகுடலில் இரத்தத்தில் சேரும்.',

  /* K2 */
  'prashna.K2.q': 'ஒரு பொம்மை கார் சாய்தளத்தில் உருளும். எங்கே அதிக தூரம்: வழுக்கும் தரைஓடில் அல்லது கம்பளத்தில்?',
  'prashna.K2.c1': 'தரைஓடில்', 'prashna.K2.c2': 'கம்பளத்தில்', 'prashna.K2.c3': 'இரண்டிலும் சமம்',
  'prashna.K2.a': 'தரைஓடில். கம்பளம் சக்கரங்களை அதிகம் தேய்க்கும்; கார் விரைவில் நிற்கும்.',
  'bodha.K2.what': 'இரண்டு பரப்புகள் தேய்ந்தால், [[friction|உராய்வு]] என்ற விசை நகர்வுக்கு எதிராகத் தள்ளும்.',
  'bodha.K2.can': 'நீ சில தளங்கள் உருளும் காரை ஏன் விரைவில் நிறுத்துகின்றன என்று விளக்கவும், நேர்மையான சோதனையைத் திட்டமிடவும் முடியும்.',
  'bodha.K2.idea': 'மென் தெரியும் பரப்பிலும் சிறிய குன்றுகள் உள்ளன. தேய்ந்தால் அவை ஒன்றோடொன்று பிடிக்கும்.',
  'bodha.K2.why': 'கரடுமுரடான பரப்பில் பெரிய குன்றுகள்; அதிகம் தேய்ந்து விரைவில் மெதுவாகும். எந்தத் தளம் அதிகம் தேய்க்கிறது என்று [[fairtest|நேர்மையான சோதனை]]யில் பார்: தளத்தை மட்டும் மாற்று.',
  'bodha.K2.example': 'அதே கார், அதே சாய்தளம், இரண்டு தளங்களில்.',
  'bodha.K2.example1': 'தரைஓடில்: அதிக தூரம் உருளும்.',
  'bodha.K2.example2': 'மணலில்: விரைவில் நிற்கும். தளம் மட்டும் மாறியது; வித்தியாசத்தைத் தளம் செய்தது.',
  'bodha.K2.example3': 'ஆக மணலில் தரைஓட்டை விட அதிக உராய்வு.',
  'bodha.K2.where': 'காலணி அடி தரையைப் பிடிக்கும். சைக்கிள் சங்கிலியில் எண்ணெய் போட்டால் மென்னே உருளும். வழுக்கும் சாலையில் மணல். கைகளைத் தேய்த்து வெப்பம்.',
  'bodha.K2.sutra': 'கரடுமுரடான பரப்புகள் அதிகம் தேயும்; உராய்வு பொருட்களை மெதுவாக்கும்.',
  'gloss.friction': 'தேய்க்கும் இரண்டு பரப்புகளுக்கிடையேயான விசை; நகர்வுக்கு எதிராக.',
  'gloss.fairtest': 'ஒரே ஒரு விஷயத்தை மட்டும் மாற்றும் சோதனை; வித்தியாசத்தை யார் செய்தது என்று தெரியும்.',
  'ramp.bumps': 'அருகில் பார்த்தால்: இரண்டு பரப்புகளில் சிறிய குன்றுகள் ஒன்றோடொன்று பிடிக்கும்.',
  'ramp.motion': 'நகர்வு', 'ramp.friction': 'உராய்வு',
  'ramp.art': '{h} உயர சாய்தளம் {s} மீது.',
  'ramp.pretend': 'm (கற்பனை அளவீடுகள்)',
  'ramp.s.tile': 'தரைஓடு', 'ramp.s.wood': 'மரம்', 'ramp.s.rug': 'கம்பளம்', 'ramp.s.sand': 'மணல்',
  'ramp.title': 'சாய்தளச் சோதனை',
  'ramp.s1': 'பார்: அதே கார், அதே உயரம், முதலில் தரைஓடு பின்னர் மணல்.',
  'ramp.showMe': 'தரைஓட்டில், பின்னர் மணலில்',
  'ramp.s1done': 'மணலில் கார் விரைவில் நின்றது: மணல் அதிகம் தேய்க்கும்.',
  'ramp.s2': 'நேர்மையான சோதனை: சாய்தளம் அப்படியே; ஒவ்வொரு தளத்தையும் முயற்சி. ஒவ்வொரு முறையும் காரை உருட்டு.',
  'ramp.height': 'சாய்தள உயரம்',
  'ramp.floor': 'தளம்',
  'ramp.roll': 'காரை உருட்டு',
  'ramp.first': '{s}-ல் கார் {d} m உருளியது.',
  'ramp.fair': 'தளம் மட்டும் மாறியது: நேர்மையான சோதனை. {s}-ல் கார் {d} m உருளியது.',
  'ramp.fairHeight': 'உயரம் மட்டும் மாறியது: உயரத்தின் நேர்மையான சோதனை. கார் {d} m உருளியது.',
  'ramp.same': 'எதுவும் மாறவில்லை; கார் மீண்டும் அதே {d} m உருளியது.',
  'ramp.unfair': 'உயரத்தையும் தளத்தையும் ஒன்றாக மாற்றினாய்; எது வித்தியாசம் செய்தது என்று சொல்ல முடியாது.',
  'ramp.s2done': 'ஒரே உயரத்திலிருந்து நான்கு தளங்களையும் முயற்சித்தாய்.',
  'ramp.s3': 'அதிக உராய்விலிருந்து குறைவாக வரிசைப்படுத்து: வரிசையில் தொடு.',
  'ramp.rankTry': 'உன் குறிகளைப் பார்: கார் விரைவில் நின்ற தளத்தில் அதிக உராய்வு.',
  'ramp.s3done': 'மணல், கம்பளம், மரம், தரைஓடு: அதிக உராய்விலிருந்து குறைவாக.',
  'ramp.atHome': 'இவை கற்பனை அளவீடுகள். வீட்டில் புத்தகமும் பொம்மை காரும் வைத்து உண்மையான சாய்தளம் முயற்சி.',
  'ramp.twoChanges': 'உயரம் 1 → 3 மற்றும் தரைஓடு → மணல்: ஒரே நேரத்தில் இரண்டு மாற்றம்.',
  'mistake.K2.intro': 'தாரா எந்தத் தளத்தில் அதிக உராய்வு என்று கண்டுபிடிக்க விரும்பினாள். ஒரு படி தவறு. எது?',
  'mistake.K2.s1': 'அவள் தாழ்ந்த சாய்தளத்தில் காரை தரைஓட்டில் உருட்டுகிறாள்.',
  'mistake.K2.s2': 'பின்னர் சாய்தளத்தை உயர்த்தி மணலில் உருட்டுகிறாள்.',
  'mistake.K2.s3': 'மணலில் கார் விரைவில் நிற்கிறது.',
  'mistake.K2.s4': 'ஆக மணலில் அதிக உராய்வு.',
  'mistake.K2.fine1': 'தாழ்ந்த சாய்தளம், தரைஓடு — தொடக்கம் சரி.',
  'mistake.K2.fine3': 'அதைத்தான் அவள் பார்த்தாள். சோதனை அமைப்பில் பிரச்சனை.',
  'mistake.K2.fine4': 'மணலில் உண்மையில் அதிக உராய்வு, ஆனால் இந்தச் சோதனை காட்ட முடியாது. முன்னால் பார்.',
  'mistake.K2.found': 'இங்கே. தாரா உயரத்தையும் தளத்தையும் ஒன்றாக மாற்றினாள்; எது வித்தியாசம் செய்தது என்று சொல்ல முடியாது. ஒன்றை மட்டும் மாற்று.',
  'explain.K2.s': 'கரடுமுரடான தளத்தில் {0} உராய்வு; கார் {1} நிற்கும். நேர்மையான சோதனையில் நீ {2} விஷயத்தை மட்டும் மாற்றுவாய்.',
  'explain.K2.more': 'அதிக', 'explain.K2.less': 'குறைவான', 'explain.K2.no': 'இல்லை',
  'explain.K2.sooner': 'விரைவில்', 'explain.K2.later': 'பின்னர்', 'explain.K2.never': 'எப்போதும் இல்லை',
  'explain.K2.one': 'ஒன்று', 'explain.K2.two': 'இரண்டு', 'explain.K2.every': 'எல்லா',
  'explain.K2.hint': 'உன் குறிகளைப் பார்; ஒவ்வொரு முறையும் எதை அப்படியே வைத்தாய் என்றும் பார்.',
  'know.K2': 'கரடுமுரடான பரப்புகள் அதிகம் தேயும், மெதுவாக்கும்; நேர்மையான சோதனையில் ஒரே ஒரு விஷயத்தை மாற்று.',

  /* R1 */
  'prashna.R1.q': 'மதியம், சூரியன் உயரமாக இருக்கும்போது, உன் நிழல் நீளமானதா, குறுகியதா?',
  'prashna.R1.c1': 'நீளமான', 'prashna.R1.c2': 'குறுகிய', 'prashna.R1.c3': 'நிழல் இல்லை',
  'prashna.R1.a': 'குறுகிய. ஒளி உனக்கு மேலே உயரமாக இருக்கும்போது நிழல் குறுகியது. காலை, மாலை நீளமானது.',
  'bodha.R1.what': 'ஒளி நேர் கோடுகளில் பயணிக்கும். ஒளி தடுக்கப்படும் இடத்தில் [[shadow|நிழல்]] உருவாகும்.',
  'bodha.R1.can': 'நிழல் எங்கே விழும், எவ்வளவு நீளமாக இருக்கும் என்று நீ கணிக்க முடியும்.',
  'bodha.R1.idea': 'விளக்கிலிருந்து நேர் கோடுகள். குச்சி சிலவற்றைத் தடுக்கும்; பின்னால் தரைக்கு ஒளி இல்லை. அந்த இருண்ட பகுதி நிழல்.',
  'bodha.R1.why': 'நிழல் எப்போதும் ஒளிக்கு மாறான பக்கம். முடிவு: குச்சியின் மேல் கடந்த கதிர் தரையைச் சந்திக்கும் இடம்; தாழ்ந்த ஒளி நீண்ட நிழல்.',
  'bodha.R1.example': 'விளக்கை நகர்த்தி குச்சியின் நிழலைப் பார்.',
  'bodha.R1.example1': 'விளக்கு தாழ்வாக: குச்சியின் மேல் கடந்த கதிர் தரையில் தூரத்தில் விழும். நீண்ட நிழல்.',
  'bodha.R1.example2': 'விளக்கு உயரமாக: கதிர் குறுகிய சாய்வில் கீழே வரும். குறுகிய நிழல்.',
  'bodha.R1.example3': 'விளக்கு தலைக்கு மேலே: நிழல் சிறியது, மதியம் உன் நிழல் போல.',
  'bodha.R1.where': 'காலை நீளமான நிழல், மதியம் குறுகியது. ஜெய்ப்பூரில் ஜந்தர் மந்தரில் உள்ள பெரிய சூரியக்கடிகாரம் நிழலால் நேரம் சொல்லும். மரத்தின் கீழ் நிழல்.',
  'bodha.R1.sutra': 'ஒளி நேராகச் செல்லும்; தடுக்கப்படும் இடத்தில், ஒளிக்கு எதிர் பக்கத்தில் நிழல்.',
  'gloss.shadow': 'ஒரு பொருள் ஒளியைத் தடுக்கும் இடத்தின் இருண்ட பகுதி.',
  'light.art': 'ஒரு விளக்கு, ஒரு குச்சி அதன் நிழல், {n} m நீளம்.',
  'light.shadowLen': 'நிழல் {n} m',
  'light.title': 'விளக்கும் குச்சியும்',
  'light.s1': 'பார்: விளக்கு உயரும்; நிழல் மாறும்.',
  'light.showMe': 'விளக்கை உயர்த்து',
  'light.s1done': 'விளக்கு எவ்வளவு உயரமோ, நிழல் அவ்வளவு குறையும்.',
  'light.s2': 'உன் முறை: நிழலை குச்சியை விட நீளமாக்கு.',
  'light.lampHeight': 'விளக்கு உயரம்',
  'light.distance': 'விளக்கு தூரம்',
  'light.s2done': 'நிழல் இப்போது {n} m, {h} m குச்சியை விட நீளம்: தாழ்ந்த அல்லது தூரமான விளக்கு நீண்ட நிழல்.',
  'light.s3': 'வேறு பொருளான குச்சிகளை முயற்சி.',
  'light.material': 'பொருள்',
  'light.m.cardboard': 'அட்டை', 'light.m.wax': 'மெழுகுத் தாள்', 'light.m.glass': 'கண்ணாடி',
  'light.kind.opaque': 'ஒளிபுகா: எல்லா ஒளியையும் தடுக்கும்; நிழல் இருண்டதாக இருக்கும்.',
  'light.kind.translucent': 'ஒளிகசியும்: சில ஒளி உள்ளே வரும்; நிழல் வெளிறியதாக இருக்கும்.',
  'light.kind.transparent': 'ஒளிஊடுருவும்: ஒளி அதிகம் உள்ளே வரும்; நிழல் மிகக் குறைவு.',
  'light.darkestQ': 'எது மிகவும் இருண்ட நிழல் தரும்?',
  'light.s3done': 'அட்டை ஒளிபுகா: எல்லா ஒளியையும் தடுக்கும். மெழுகுத் தாள் ஒளிகசியும்; கண்ணாடி ஒளிஊடுருவும்.',
  'light.s3try': 'ஒவ்வொரு நிழலையும் பார்: எது அதிகம் இருண்டது?',
  'mistake.R1.intro': 'அலி குச்சியின் மீது கை விளக்கைப் பிரகாசிக்க வைத்தான். ஒரு படி தவறு. எது?',
  'mistake.R1.s1': 'அலி தரையில் நிற்கும் குச்சியின் மீது கை விளக்கைப் பிரகாசிக்கிறான்.',
  'mistake.R1.s2': 'ஒளி நேர் கோடுகளில் செல்லும்; குச்சி அதில் சிலவற்றைத் தடுக்கும்.',
  'mistake.R1.s3': 'அவன் கை விளக்கைத் தாழ்த்துகிறான்; நிழல் குறைகிறது.',
  'mistake.R1.s4': 'ஆக மாலை தாழ்ந்த சூரியன் குறுகிய நிழலை உண்டாக்கும்.',
  'mistake.R1.fine1': 'சரி: ஒளியும் அதைத் தடுக்கும் பொருளும்.',
  'mistake.R1.fine2': 'சரி: அப்படித்தான் நிழல் உருவாகும்.',
  'mistake.R1.fine4': 'முந்தைய படியைப் பின்பற்றுகிறது; அதுவும் தவறு. முன்னால் பார்.',
  'mistake.R1.found': 'இங்கே. தாழ்ந்த ஒளிக்கு நீண்ட நிழல்: குச்சியின் மேல் கடந்த கதிர் தரையில் தூரத்தில் விழும்.',
  'explain.R1.s': 'ஒளி {0} கோடுகளில் பயணிக்கும். ஒளி உயர்ந்தால் நிழல் {1}.',
  'explain.R1.straight': 'நேர்', 'explain.R1.curved': 'வளைந்த', 'explain.R1.zigzag': 'கொடுக்கி',
  'explain.R1.longer': 'நீளமான', 'explain.R1.shorter': 'குறுகிய', 'explain.R1.gone': 'மறைந்த',
  'explain.R1.hint': 'புள்ளிக்கோட்டுக் கதிர்களைப் பார்; விளக்கு உயர்ந்தபோது நிழல் என்ன ஆனது.',
  'know.R1': 'ஒளி நேர் கோடுகளில் பயணிக்கும்; தடுக்கும் பொருளின் ஒளிக்கு எதிர் பக்கத்தில் நிழல்; உயர ஒளிக்கு குறுகிய நிழல்.'
});
